import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.-EXvoMUp.js";const u=JSON.parse('{"title":"HybridID","description":"","frontmatter":{},"headers":[],"relativePath":"api/id.md","filePath":"api/id.md"}'),r={name:"api/id.md"};function d(n,e,s,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="hybridid" tabindex="-1">HybridID <a class="header-anchor" href="#hybridid" aria-label="Permalink to &quot;HybridID&quot;">​</a></h1><p><code>HybridID</code> wraps a non-negative bigint. Decimal strings are normalized immediately, so comparison and hexadecimal conversion use integer semantics.</p><h2 id="constructor" tabindex="-1">constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;constructor&quot;">​</a></h2><p><code>new HybridID(id: bigint | string)</code> accepts a non-negative bigint or a decimal digit string. Negative values, blank strings, hexadecimal strings, and fractional values throw.</p><h2 id="conversions" tabindex="-1">Conversions <a class="header-anchor" href="#conversions" aria-label="Permalink to &quot;Conversions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Result</th></tr></thead><tbody><tr><td><code>toBigInt(): bigint</code></td><td>Raw integer</td></tr><tr><td><code>toString(): string</code></td><td>Decimal digits</td></tr><tr><td><code>valueOf(): bigint</code></td><td>Raw integer for numeric coercion</td></tr><tr><td><code>toHex(): string</code></td><td>Hex digits without a prefix</td></tr><tr><td><code>toBase62(): string</code></td><td>Base62 integer digits</td></tr><tr><td><code>toBase32(): string</code></td><td>Base32 integer digits</td></tr><tr><td><code>toBase64(): string</code></td><td>Base64 integer digits, without padding</td></tr></tbody></table><p>See <a href="./../encoding.html">encoding and storage</a> for alphabets and precision rules.</p><h2 id="factories" tabindex="-1">Factories <a class="header-anchor" href="#factories" aria-label="Permalink to &quot;Factories&quot;">​</a></h2><p><code>HybridID.fromBase62(text)</code>, <code>fromBase32(text)</code>, <code>fromBase64(text)</code>, and <code>fromHex(text)</code> each return a new <code>HybridID</code> and reject empty or invalid input. <code>fromHex</code> expects digits without a <code>0x</code> prefix.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><p><code>isEqual(other)</code>, <code>isLessThan(other)</code>, and <code>isGreaterThan(other)</code> compare underlying numeric values and return booleans. They work consistently whether IDs were constructed from bigint values or decimal strings.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p><code>HybridID.isValidBase62(text)</code>, <code>isValidBase32(text)</code>, and <code>isValidBase64(text)</code> check non-empty strings against the corresponding integer alphabet. <code>=</code> padding is not allowed. These helpers check syntax, without checking a generator&#39;s configured layout.</p><h2 id="serialize" tabindex="-1">serialize <a class="header-anchor" href="#serialize" aria-label="Permalink to &quot;serialize&quot;">​</a></h2><p><code>serialize(): string</code> returns JSON with a decimal string ID, such as <code>&#39;{&quot;id&quot;:&quot;123&quot;}&#39;</code>.</p><h2 id="deserialize" tabindex="-1">deserialize <a class="header-anchor" href="#deserialize" aria-label="Permalink to &quot;deserialize&quot;">​</a></h2><p><code>HybridID.deserialize(serialized: string): HybridID</code> parses JSON and validates the <code>id</code> string. Malformed JSON, missing IDs, non-string values, and invalid decimal values throw.</p><h2 id="generaterandom" tabindex="-1">generateRandom <a class="header-anchor" href="#generaterandom" aria-label="Permalink to &quot;generateRandom&quot;">​</a></h2><p><code>HybridID.generateRandom(): HybridID</code> uses cryptographic randomness to produce a <strong>32-bit</strong> random value. This helper has a much smaller collision space than a full generator ID and does not encode the timestamp/machine layout.</p>',19)])])}const m=a(r,[["render",d]]);export{u as __pageData,m as default};
